Hey @balazsorban44, the following is my `next.config.js`. 
As I mentioned in my previous comment, I do not use a custom server.

```js
const basePath = '/app'

/**
 * @type {import('next').NextConfig}
 */
const nextConfig = {
  basePath,
  assetPrefix: basePath,
  poweredByHeader: false,
  nx: { svgr: false },
  eslint: {
    ignoreDuringBuilds: true
  },
  env: {
    appBasePath: basePath
  },
  sentry: {
    disableServerWebpackPlugin: disableSentry,
    disableClientWebpackPlugin: disableSentry
  },
  async redirects() {
    return [
      {
        source: '/liveness',
        destination: '/app/api/health/liveness',
        basePath: false,
        permanent: false
      },
      {
        source: '/ready',
        destination: '/app/api/health/ready',
        basePath: false,
        permanent: false
      },
      {
        source: '/startup',
        destination: '/app/api/health/startup',
        basePath: false,
        permanent: false
      },
      {
        source: `/:path((?!${basePath.replace('/', '')}).*)`,
        destination: `${basePath}/:path*`,
        basePath: false,
        permanent: false
      }
    ]
  }
}

const plugins = withPlugins([withNx, withAssets], nextConfig)

module.exports = withSentryConfig(plugins, sentryOptions)
```
